//
// 🔴 가격 문구의 괄호 속 외화 환산은 참고용 개산가다(2026-08 환율 기준, USD≈1,350/JPY≈9.2/CNY≈188/
// TWD≈43/VND≈0.0551/INR≈16.2/EUR≈1,460/MYR≈288 원). 실제 결제는 이니시스/PortOne 정책상 원화(KRW)로
// 승인되며(일본만 JPY, docs/context/payment-gating.md 참고), 이 환산가는 청구 금액이 아니다.

